import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.mOeOKQKb.js";var i=JSON.parse(`{"title":"Chat day-file HTML comments","description":"","frontmatter":{},"headers":[],"relativePath":"custom-markdown/chat-day-file-comments.md","filePath":"custom-markdown/chat-day-file-comments.md"}`),a={name:`custom-markdown/chat-day-file-comments.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="chat-day-file-html-comments" tabindex="-1">Chat day-file HTML comments <a class="header-anchor" href="#chat-day-file-html-comments" aria-label="Permalink to “Chat day-file HTML comments”">​</a></h1><p>채팅 “나 자신과 대화” 일별 마크다운 파일(<code>.chat-with-myself/YYYY-MM-DD.md</code>)의 <strong>저장 포맷</strong>. MdPreview 본문 문법이 아니라 메시지 경계·메타데이터 마커다.</p><h2 id="문법-개요" tabindex="-1">문법 (개요) <a class="header-anchor" href="#문법-개요" aria-label="Permalink to “문법 (개요)”">​</a></h2><div class="language-html"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">&lt;!-- chat-msg id=&quot;…&quot; at=&quot;…&quot; tz=&quot;…&quot; source=&quot;compose&quot; group=&quot;나&quot; … --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">메시지 본문</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">&lt;!-- chat-msg-deleted id=&quot;…&quot; at=&quot;…&quot; --&gt;</span></span></code></pre></div><h2 id="spec-interop" tabindex="-1">Spec (interop) <a class="header-anchor" href="#spec-interop" aria-label="Permalink to “Spec (interop)”">​</a></h2><p>기준 구현: <code>format.js</code> (<code>parseDayFile</code>, <code>serializeMessage</code>, <code>serializeDeletedMarker</code>).</p><h3 id="_1-attribute-grammar-all-chat-html-comments" tabindex="-1">1. Attribute grammar (all chat HTML comments) <a class="header-anchor" href="#_1-attribute-grammar-all-chat-html-comments" aria-label="Permalink to “1. Attribute grammar (all chat HTML comments)”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ATTRS := ( WS KEY &quot;=&quot; &#39;&quot;&#39; VALUE &#39;&quot;&#39; )*</span></span>
<span class="line"><span>KEY   := /[\\w-]+/</span></span>
<span class="line"><span>VALUE := /[^&quot;]*/          # after unescape on read</span></span></code></pre></div><p>Parse: <code>/([\\w-]+)=&quot;([^&quot;]*)&quot;/g</code> over the attribute region.</p><p><strong>Write escape</strong> (<code>escapeAttr</code>): <code>&amp;</code> → <code>&amp;amp;</code>, <code>&quot;</code> → <code>&amp;quot;</code>, <code>&lt;</code> → <code>&amp;lt;</code>, <code>\\r\\n</code>/<code>\\n</code> → <code>&amp;#10;</code>, strip lone <code>\\r</code>.</p><p><strong>Read unescape</strong> (<code>unescapeAttr</code>): reverse <code>&amp;#10;</code>, <code>&amp;lt;</code>, <code>&amp;quot;</code>, <code>&amp;amp;</code> (order: <code>&amp;#10;</code> then <code>&amp;lt;</code> then <code>&amp;quot;</code> then <code>&amp;amp;</code>).</p><h3 id="_2-message-start" tabindex="-1">2. Message start <a class="header-anchor" href="#_2-message-start" aria-label="Permalink to “2. Message start”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MSG_START := &quot;&lt;!--&quot; WS &quot;chat-msg&quot; WS ATTRS &quot;--&gt;&quot; WS?</span></span></code></pre></div><p>Regex: <code>/&lt;!--\\s*chat-msg\\s+([^&gt;]*?)--&gt;\\s*/g</code></p><p><strong>Required attrs:</strong> <code>id</code>, <code>at</code> (ISO UTC).<br><strong>Common attrs:</strong> <code>tz</code>, <code>source</code>, <code>group</code>.<br><strong>Optional:</strong> <code>replyTo</code>, <code>replySnippet</code>, <code>replyGroup</code>, <code>editedAt</code>, <code>pinnedAt</code>, <code>notePath</code>, <code>collapsed</code> (<code>&quot;1&quot;</code>), <code>markdown</code> (<code>&quot;1&quot;</code>), <code>reactions</code>, <code>reactionsAt</code>.</p><p><strong>Body region:</strong> from end of start marker to the next <code>chat-msg</code> start (or EOF). Strip leading single <code>\\n</code>, trailing newlines. Strip interleaved <code>chat-msg-deleted</code> markers found inside the slice from the body text (tombstones are global, not part of body).</p><p><code>markdown</code> truthy values on read: <code>true</code> | <code>&quot;1&quot;</code> | <code>&quot;true&quot;</code>; missing → false.</p><h3 id="_3-deletion-tombstone" tabindex="-1">3. Deletion tombstone <a class="header-anchor" href="#_3-deletion-tombstone" aria-label="Permalink to “3. Deletion tombstone”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MSG_DELETED := &quot;&lt;!--&quot; WS &quot;chat-msg-deleted&quot; WS ATTRS &quot;--&gt;&quot;</span></span></code></pre></div><p>Regex: <code>/&lt;!--\\s*chat-msg-deleted\\s+([^&gt;]*?)--&gt;/g</code></p><p>Attrs: <code>id</code> (required), <code>at</code> (optional; default epoch ISO if missing when indexing).</p><p>Canonical write:</p><div class="language-html"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">&lt;!-- chat-msg-deleted id=&quot;{id}&quot; at=&quot;{at}&quot; --&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\n</span></span></code></pre></div><h3 id="_4-day-file-layout" tabindex="-1">4. Day file layout <a class="header-anchor" href="#_4-day-file-layout" aria-label="Permalink to “4. Day file layout”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DAY_FILE := ( MSG | TOMBSTONE | other )*</span></span></code></pre></div><p>Messages and tombstones may be interleaved. Parser collects all tombstones into <code>deletedIds</code> / <code>deletedAtById</code>, then walks all <code>chat-msg</code> starts for message list.</p><h3 id="_5-legacy-optional-to-implement" tabindex="-1">5. Legacy (optional to implement) <a class="header-anchor" href="#_5-legacy-optional-to-implement" aria-label="Permalink to “5. Legacy (optional to implement)”">​</a></h3><ul><li>Trailing <code>&lt;!-- chat-edits id=&quot;…&quot; --&gt;…&lt;!-- /chat-edits --&gt;</code> — legacy inline history; prefer sidecar <code>.chat-with-myself/edits/&lt;id&gt;/</code>.</li><li>Edit version files: <code>&lt;!-- chat-edit-version at=&quot;…&quot; group=&quot;…&quot; --&gt;</code> (<code>editHistory.ts</code>).</li></ul><h3 id="_6-non-goals" tabindex="-1">6. Non-goals <a class="header-anchor" href="#_6-non-goals" aria-label="Permalink to “6. Non-goals”">​</a></h3><ul><li>Rendering these comments as visible Markdown</li><li>JSON body instead of HTML comments (not the on-disk format)</li></ul><h2 id="구현" tabindex="-1">구현 <a class="header-anchor" href="#구현" aria-label="Permalink to “구현”">​</a></h2><table tabindex="0"><thead><tr><th>역할</th><th>경로</th></tr></thead><tbody><tr><td>직렬화·파싱</td><td><code>src/utils/chatWithMyself/format.js</code></td></tr><tr><td>reactions attr</td><td><code>src/utils/chatWithMyself/reactions.js</code></td></tr><tr><td>일별 경로</td><td><code>src/utils/chatWithMyself/paths.js</code></td></tr></tbody></table>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};